30	/// What `@types/react` declares (`key`, `ref`, `children` on `PropsWithChildren`, HTML attributes). Reported with the
31	/// flag set when the request asks for the name; what to do with them is the session's policy, not ours.
32	fn is_react_declared(property: &SymbolInfo) -> bool {
33	    property.declarations.iter().any(|declaration| declared_in(declaration).contains("/@types/react/"))
34	}
