55	/// The symbol `export` names in `module`: the export of exactly that name, through an alias to what it aliases, then
56	/// each property an attached sub-component is reached through. `Err` says why there is none, or why it is not the
57	/// component the extractor found: one declared in another file.
58	async fn exported_symbol(
59	    rpc: &Rpc,
60	    module: &Module,
61	    export: &ComponentExport,
62	) -> Result<Result<SymbolInfo, String>, CallError> {
63	    let Some(symbol) = module.exports.iter().find(|symbol| symbol.name == export.name) else {
64	        return Ok(Err(format!("the checker finds no export `{}` in its module", export.name)));
65	    };
66	    let mut symbol = if symbol.flags & flag::SYMBOL_ALIAS != 0 {
67	        rpc.aliased_symbol(&symbol.reference).await?
68	    } else {
69	        symbol.clone()
70	    };
