1	//! The checker a run asks, and the one place that picks which: the `tsrs` crates linked into this process, or a
2	//! `tsc --api` process when an explicit `tsc_path` names one (the Go `typescript@7.1` the tests and the parity gate
3	//! run, or a `tsrs` binary). Both answer the same methods with the same JSON, so [`crate::rpc`] does not know which.
4	//!
5	//! The linked checker answers on threads of its own with a 512 MiB stack, the stack the `tsrs` binary serves on. A
6	//! query runs on the thread that calls it, and a type nested 2,000 deep overflows a default 2 MiB thread: a stack
7	//! overflow aborts the whole process and cannot be caught. Callers on any thread send it requests over a channel, one
8	//! per checker thread (a lane), and each thread answers its own one at a time, in the order they arrive; a run that asks
9	//! several programs at once sends each program's requests down a lane of its own ([`Client::lane`]). A panic inside the
10	//! checker comes back as an error to the request that caused it (`tsrs_api` catches it), and the session keeps
11	//! answering.
12	
13	use std::sync::atomic::{AtomicUsize, Ordering};
14	use std::sync::{Arc, mpsc};
15	use std::thread::JoinHandle;
16	use std::time::Duration;
17	
18	use caliper_docgen_tsc_client::{MalformedFrameReason, Supervisor, SupervisorConfig, TscClientError};
19	use camino::Utf8Path;
20	use serde_json::Value;
21	use serde_json::value::RawValue;
22	use tokio::sync::oneshot;
23	use tsrs_api::{Handler, Response, Session, SessionOptions};
24	use tsrs_vfs::{FS, bundled, osvfs};
25	
26	use crate::locate;
27	
28	/// The stack of the thread the linked checker answers on: what the `tsrs` binary gives each of its threads.
29	const CHECKER_STACK_BYTES: usize = 512 << 20;
30	
31	/// The JSON-RPC code the `tsrs` and `tsc` processes answer a failed request with (`jsonrpc.CodeInternalError`); the
32	/// message is the error's text, as here.
33	const INTERNAL_ERROR: i64 = -32603;
34	
35	/// How to start a checker: an explicit binary runs as a process, none links the bundled one.
36	pub(crate) struct Start<'a> {
37	    pub(crate) project_root: &'a Utf8Path,
38	    pub(crate) tsc_path: Option<&'a Utf8Path>,
39	    pub(crate) expected_versions: &'static [&'static str],
40	    pub(crate) timeout: Duration,
41	    pub(crate) extra_env: &'a [(String, String)],
42	    /// How many threads the linked checker answers on: requests about different programs of its session run at once.
43	    /// A process answers on its own terms.
44	    pub(crate) threads: usize,
45	}
46	
47	/// A running checker.
48	pub(crate) enum Backend {
49	    /// A `tsc --api` process for an explicit binary.
50	    Process(Box<Supervisor>),
51	    /// The checker linked into this process, on its own thread.
52	    InProcess(InProcess),
53	}
54	
55	impl Backend {
56	    /// The checker `start` asks for. An explicit path that does not exist, a binary that does not start or is not a
57	    /// supported version, or a checker thread that cannot be spawned, is an error that says so.
58	    pub(crate) async fn start(start: Start<'_>) -> Result<Backend, String> {
59	        let Some(tsc_path) = start.tsc_path else {
60	            return InProcess::start(start.project_root, start.threads).map(Backend::InProcess);
61	        };
62	        let tsc_path = locate::explicit_tsc(tsc_path)?;
63	        let mut config = SupervisorConfig::new(tsc_path, start.project_root.to_owned(), start.expected_versions);
64	        config.handshake_timeout = start.timeout;
65	        config.extra_env = start.extra_env.to_vec();
66	        Supervisor::spawn(config)
67	            .await
68	            .map(|supervisor| Backend::Process(Box::new(supervisor)))
69	            .map_err(|error| error.to_string())
70	    }
71	
72	    /// How many programs a run asks at once: one per thread of the linked checker, one for a process (whose requests
73	    /// this client sends one at a time).
74	    pub(crate) fn parallel_programs(&self) -> usize {
75	        match self {
76	            Backend::Process(_) => 1,
77	            Backend::InProcess(checker) => checker.threads,
78	        }
79	    }
80	
81	    pub(crate) fn client(&self) -> Client {
82	        match self {
83	            Backend::Process(supervisor) => Client::Process(supervisor.client()),
84	            Backend::InProcess(checker) => Client::InProcess(checker.client.clone()),
85	        }
86	    }
87	
88	    pub(crate) fn is_alive(&self) -> bool {
89	        match self {
90	            Backend::Process(supervisor) => supervisor.is_alive(),
91	            Backend::InProcess(checker) => !checker.thread.is_finished(),
92	        }
93	    }
94	
95	    /// The operating system's id of the checker process; `None` for the linked checker, which is this process.
96	    pub(crate) fn process_id(&self) -> Option<u32> {
97	        match self {
98	            Backend::Process(supervisor) => supervisor.process_id(),
99	            Backend::InProcess(_) => None,
100	        }
101	    }
102	
103	    /// Stops the checker. A process is reaped. The linked checker's thread finishes the request it is in, closes its
104	    /// session and exits on its own: it is not waited for, so a hung request cannot hold the caller.
105	    pub(crate) async fn shutdown(self) {
106	        match self {
107	            Backend::Process(supervisor) => {
108	                if let Err(error) = (*supervisor).shutdown().await {
109	                    tracing::debug!(%error, "the checker process did not shut down cleanly");
110	                }
111	            }
112	            Backend::InProcess(checker) => checker.client.stop(),
113	        }
114	    }
115	}
116	
117	/// A handle that sends requests to a running checker. Cheap to clone.
118	#[derive(Clone)]
119	pub(crate) enum Client {
120	    Process(caliper_docgen_tsc_client::Client),
121	    InProcess(Linked),
122	}
123	
124	impl Client {
125	    /// The client whose requests the `lane`th thread of the linked checker answers ([`InProcess::start`]); a process
126	    /// has one lane, so its client is itself.
127	    pub(crate) fn lane(&self, lane: usize) -> Client {
128	        match self {
129	            Client::Process(client) => Client::Process(client.clone()),
130	            Client::InProcess(linked) => Client::InProcess(Linked { lanes: linked.lanes.clone(), lane }),
131	        }
132	    }
133	
134	    /// One request, its answer the `result` as the JSON text it arrived as. The wait is bounded by `deadline`; an
135	    /// error is the one the process route would give for the same failure.
136	    pub(crate) async fn request_raw(
137	        &self,
138	        method: &str,
139	        params: Value,
140	        deadline: Duration,
141	    ) -> Result<Box<RawValue>, TscClientError> {
142	        match self {
143	            Client::Process(client) => Ok(client.request_raw(method, params, deadline).await?.result),
144	            Client::InProcess(linked) => linked.request(method, params, deadline).await,
145	        }
146	    }
147	}
148	
149	/// The linked checker: the thread that owns its session, and the way to it.
150	pub(crate) struct InProcess {
151	    client: Linked,
152	    thread: JoinHandle<()>,
153	    threads: usize,
154	}
155	
156	enum Job {
157	    Request(Asked),
158	    /// Close the session and end the thread; requests sent after it fail as from a stopped checker.
159	    Stop,
160	}
161	
162	struct Asked {
163	    method: String,
164	    params: Vec<u8>,
165	    reply: oneshot::Sender<Result<String, String>>,
166	}
167	
168	/// The sending ends of the linked checker's queues, one per thread, and the one this client sends to.
169	#[derive(Clone)]
170	pub(crate) struct Linked {
171	    lanes: Arc<[mpsc::Sender<Job>]>,
172	    lane: usize,
173	}
174	
175	impl InProcess {
176	    /// Spawns the checker thread, which creates its session there: the session's work, from the first request on,
177	    /// runs on that thread's stack. With `threads` above one it starts as many more, each answering a queue of its own
178	    /// (a lane, [`Client::lane`]) on the same session: requests about one program wait for each other (each program
179	    /// has one checker, which `tsrs_api` locks for the length of a request), so a run that sends the requests about
180	    /// each of its programs down a lane of its own has them answered at once.
181	    pub(crate) fn start(project_root: &Utf8Path, threads: usize) -> Result<InProcess, String> {
182	        let (lanes, queues): (Vec<_>, Vec<_>) = (0..threads.max(1)).map(|_| mpsc::channel()).unzip();
183	        let threads = lanes.len();
184	        let cwd = project_root.to_string();
185	        let thread = std::thread::Builder::new()
186	            .name("caliper-checker".to_string())
187	            .stack_size(CHECKER_STACK_BYTES)
188	            .spawn(move || serve(cwd, queues))
189	            .map_err(|error| format!("could not start the checker thread: {error}"))?;
190	        Ok(InProcess { client: Linked { lanes: lanes.into(), lane: 0 }, thread, threads })
191	    }
192	}
193	
194	impl Linked {
195	    async fn request(&self, method: &str, params: Value, deadline: Duration) -> Result<Box<RawValue>, TscClientError> {
196	        let params = serde_json::to_vec(&params).map_err(|error| TscClientError::Serialize(Arc::new(error)))?;
197	        let (reply, answer) = oneshot::channel();
198	        let asked = Asked { method: method.to_string(), params, reply };
199	        let Some(jobs) = self.lanes.get(self.lane % self.lanes.len().max(1)) else {
200	            return Err(TscClientError::SessionClosed);
201	        };
202	        if jobs.send(Job::Request(asked)).is_err() {
203	            return Err(TscClientError::SessionClosed);
204	        }
205	        let answered = match tokio::time::timeout(deadline, answer).await {
206	            Ok(Ok(answered)) => answered,
207	            // The thread ended without answering: stopped, or its session could not be created.
208	            Ok(Err(_dropped)) => return Err(TscClientError::SessionClosed),
209	            Err(_elapsed) => return Err(TscClientError::Timeout { method: method.to_string(), after: deadline }),
210	        };
211	        match answered {
212	            Ok(text) => RawValue::from_string(text)
213	                .map_err(|_invalid| TscClientError::MalformedFrame { reason: MalformedFrameReason::InvalidJson }),
214	            Err(message) => Err(TscClientError::RpcError { code: INTERNAL_ERROR, message, data: None }),
215	        }
216	    }
217	
218	    fn stop(&self) {
219	        // A thread that already ended has nothing to stop.
220	        for jobs in self.lanes.iter() {
221	            jobs.send(Job::Stop).ok();
222	        }
223	    }
224	}
225	
226	/// The checker threads: one session, each thread answering the requests of its queue in turn until it is stopped or
227	/// every sender is gone. The first thread creates the session and starts the others; the last to leave closes it.
228	fn serve(cwd: String, queues: Vec<mpsc::Receiver<Job>>) {
229	    let fs: Arc<dyn FS> = Arc::new(bundled::wrap_fs(osvfs::fs()));
230	    let session = Session::new(SessionOptions::new(cwd, bundled::lib_path(), fs, false));
231	    let left = Arc::new(AtomicUsize::new(queues.len()));
232	    let mut queues = queues.into_iter();
233	    let Some(own) = queues.next() else { return session.close() };
234	    for (index, queue) in queues.enumerate() {
235	        let (session, still) = (session.clone(), left.clone());
236	        let spawned = std::thread::Builder::new()
237	            .name(format!("caliper-checker-{}", index + 1))
238	            .stack_size(CHECKER_STACK_BYTES)
239	            .spawn(move || answer(&session, queue, &still));
240	        // Its queue is dropped with the closure, so its lane's requests fail as from a stopped checker.
241	        if spawned.is_err() {
242	            left.fetch_sub(1, Ordering::AcqRel);
243	        }
244	    }
245	    answer(&session, own, &left);
246	}
247	
248	/// One checker thread: the requests of `queue` in turn, until it is stopped or every sender is gone. The last thread
249	/// of the session (`left`) closes it.
250	fn answer(session: &Session, queue: mpsc::Receiver<Job>, left: &AtomicUsize) {
251	    for job in queue {
252	        let asked = match job {
253	            Job::Request(asked) => asked,
254	            Job::Stop => break,
255	        };
256	        // A caller that stopped waiting (its deadline passed, its run ended) is not answered.
257	        if asked.reply.is_closed() {
258	            continue;
259	        }
260	        let answer = match session.handle_request(&asked.method, &asked.params) {
261	            Ok(Response::Json(text)) => Ok(text),
262	            Ok(Response::Binary(_)) => Err(format!("{} answered in binary, not JSON", asked.method)),
263	            Err(error) => Err(error.to_string()),
264	        };
265	        asked.reply.send(answer).ok();
266	    }
267	    if left.fetch_sub(1, Ordering::AcqRel) == 1 {
268	        session.close();
269	    }
270	}
