fn is_valid_identifier(name: &str) -> bool {
    let mut chars = name.chars();
    let Some(first) = chars.next() else { return false };
    (first.is_alphabetic() || first == '_' || first == '$')
        && chars.all(|c| c.is_alphanumeric() || c == '_' || c == '$')
}

#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(tag = "type", rename_all = "camelCase", rename_all_fields = "camelCase")]
pub enum OpaqueReason {
    ConditionalType,
    MappedType,
    ModuleAugmentation,
    RuntimeDependent {
        function_name: std::string::String,
    },
    UnresolvableImport {
        specifier: std::string::String,
    },
    PandaCodegenMissing,
    DepthExceeded,
    IndexedAccess {
        expression: std::string::String,
    },
    UnsupportedExpression,
}

impl OpaqueReason {
    pub const KINDS: [&'static str; 9] = [
        "conditionalType",
        "mappedType",
        "moduleAugmentation",
        "runtimeDependent",
        "unresolvableImport",
        "pandaCodegenMissing",
        "depthExceeded",
        "indexedAccess",
        "unsupportedExpression",
    ];

    pub fn kind(&self) -> &'static str {
        match self {
            OpaqueReason::ConditionalType => "conditionalType",
            OpaqueReason::MappedType => "mappedType",
            OpaqueReason::ModuleAugmentation => "moduleAugmentation",
            OpaqueReason::RuntimeDependent { .. } => "runtimeDependent",
