/// nothing instead of the intended real package.
pub(crate) fn canonicalize_first_src_dir(src_dirs: &[Utf8PathBuf]) -> Option<Utf8PathBuf> {
    src_dirs.first().and_then(|dir| crate::canonical_path::canonicalize(dir).ok())
